/// <summary>
/// CB503_CustomerNumbering
/// The <c>METDirPartyQuickCreateFormEventHandlers</c> class defines event handlers
/// for <c>DirPartyQuickCreateForm</c> form events.
/// </summary>
public final class METDirPartyQuickCreateFormEventHandlers
{
    FormDataSource      dirPartyEntityDataSource;
    FormDataSource      dirPartyTableDataSource;
    FormDataSource      dirPersonNameDataSource;
    boolean             initialized;
    boolean             isCustGroupValueSetOnce;
    FormRun             parentForm;

}

Method.Source:
    /// <summary>
    /// Creates a new instance of this form event handler class and registers it with the base form.
    /// </summary>
    /// <param name = "_formRun">An instance of the form being extended.</param>
    public void new(FormRun _formRun)
    {
        initialized = false;

        parentForm = _formRun;

        // Register this event handlers with the main form
        _formRun.registerExtensionInstance(classStr(METDirPartyQuickCreateFormEventHandlers), this);
    }

/// <summary>
/// The OnInitializing event handler for the <c>DirPartyQuickCreateForm</c> form.
/// </summary>
/// <param name="_sender">The instance of the form being extended.</param>
/// <param name="_e">The args for the event.</param>
[FormEventHandler(formStr(DirPartyQuickCreateForm), FormEventType::Initializing)]
public static void initializingFormEventHandler(xFormRun _sender, FormEventArgs _e)
{
    METDirPartyQuickCreateFormEventHandlers extensionInstance = new METDirPartyQuickCreateFormEventHandlers(_sender as FormRun);
}

    /// <summary>
    /// The OnInitialized event handler for the <c>DirPartyQuickCreateForm</c> form.
    /// </summary>
    /// <param name="_sender">The instance of the form being extended.</param>
    /// <param name="_e">The args for the event.</param>
    [FormEventHandler(formStr(DirPartyQuickCreateForm), FormEventType::Initialized)]
    public static void initializedFormEventHandler(xFormRun _sender, FormEventArgs _e)
    {
        FormRun formRun = _sender as FormRun;

        METDirPartyQuickCreateFormEventHandlers extensionInstance = formRun.getExtensionInstance(classStr(METDirPartyQuickCreateFormEventHandlers));
        extensionInstance.registerInstanceEventHandlers(formRun);

    }

/// <summary>
/// Get Data source variabales from the form.
/// </summary>
/// <param name = "_formRun">An instance of the form being extended.</param>
private void retrieveFormDataSources(FormRun _formRun)
{
    dirPartyEntityDataSource    = _formRun.dataSource(formDataSourceStr(DirPartyQuickCreateForm, DirPartyEntity)) as FormDataSource;
    dirPartyTableDataSource     = _formRun.dataSource(formDataSourceStr(DirPartyQuickCreateForm, DirPartyTable)) as FormDataSource;
    dirPersonNameDataSource     = _formRun.dataSource(formDataSourceStr(DirPartyQuickCreateForm, DirPersonName)) as FormDataSource;
}

    /// <summary>
    /// Register override methods for some controls.
    /// </summary>
    /// <param name = "_formRun">An instance of the form being extended.</param>
    private void registerInstanceEventHandlers(FormRun _formRun)
    {
        if (initialized)
        {
            return;
        }

        initialized = true;

        this.retrieveFormDataSources(_formRun);

        this.registerCustTableEventHandlers(_formRun);
    }

/// <summary>
/// Register new method for dataChanged for CustGroup control.
/// </summary>
/// <param name = "_formRun">An instance of the form being extended.</param>
private void registerCustTableEventHandlers(FormRun _formRun)
{
    if (dirPartyEntityDataSource.table() == tablenum(CustTable))
    {
        dirPartyEntityDataSource.object(fieldnum(CustTable, CustGroup)).registerOverrideMethod(methodstr(FormDataObject,dataChanged), methodStr(METDirPartyQuickCreateFormEventHandlers, custGroupDataChangedOverride), this);
        dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).allowEdit(false);
        dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).registerOverrideMethod(methodstr(FormDataObject,lookupReference), methodStr(METDirPartyQuickCreateFormEventHandlers, businessUnitLookupReferenceOverride), this);
        dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).registerOverrideMethod(methodstr(FormDataObject,modified), methodStr(METDirPartyQuickCreateFormEventHandlers, businessUnitModifiedOverride), this);
    }
}

    /// <summary>
    /// New method for dataChanged for CustGroup control
    /// </summary>
    /// <param name = "_formDataObject">An instance of the form control.</param>
    private void businessUnitModifiedOverride(FormDataObject _formDataObject)
    {
        _formDataObject.dataChanged();
        if (dirPartyEntityDataSource.table() == tablenum(CustTable))
        {
            if (!CustTable::isDelayNumberSequenceGeneration())
            {
                METBusinessUnitTableRefRecId    businessUnitTableRefRecId = _formDataObject.getValue();

                METBusinessUnit   businessUnit = METBusinessUnit::findRecId(businessUnitTableRefRecId);
                if (businessUnit.RecId)
                {
                    NumberSeqFormHandler numSeqFormHandler = CustTable::getNumberSeqFormHandler(parentForm, dirPartyEntityDataSource);
                    FormDataObject numberSequenceFormDataObject = numSeqFormHandler.parmFormDataSource().object(numSeqFormHandler.parmFieldIdNum());
                    numberSequenceFormDataObject.setValue(CustTable::metGetCustomerNumSeqRec(businessUnitTableRefRecId));
                }
            }
        }
    }

/// <summary>
/// New method for dataChanged for CustGroup control
/// </summary>
/// <param name = "_formDataObject">An instance of the form control.</param>
private void custGroupDataChangedOverride(FormDataObject _formDataObject)
{
    CustGroupId     custGroupId;
    _formDataObject.dataChanged();
    custGroupId = _formDataObject.getValue();
    if (dirPartyEntityDataSource.table() == tablenum(CustTable))
    {
        CustGroup   custGroup = CustGroup::find(custGroupId);
        NumberSeqFormHandler numSeqFormHandler = CustTable::getNumberSeqFormHandler(parentForm, dirPartyEntityDataSource);
        FormDataObject numberSequenceFormDataObject = numSeqFormHandler.parmFormDataSource().object(numSeqFormHandler.parmFieldIdNum());
        if (custGroup.METEnableCustNumbering)
        {
            numberSequenceFormDataObject.setValue('');
            dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).allowEdit(true);
            dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).mandatory(true);
        }
        else
        {
            dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).allowEdit(false);
            dirPartyEntityDataSource.object(fieldnum(CustTable, METBusinessUnitTableRefRecId)).mandatory(false);
        }
        CustTable   custTable = dirPartyEntityDataSource.cursor();
        custTable.METBusinessUnitTableRefRecId = 0;
    }
}

/// <summary>
/// look up for Business unit
/// </summary>
/// <param name = "_lookup">Form reference control</param>
/// <returns>Business unit</returns>
public Common businessUnitLookupReferenceOverride(FormReferenceControl _lookup)
{
    return METBusinessUnit::lookupReferenceType(_lookup);
}

/// <summary>
/// Validate cuxtomer number
/// </summary>
/// <param name="_formRun">The instance of the form.</param>
/// <param name="_dataSource">Data source.</param>
private static void validateNewCustomerAccountNum(FormRun _formRun, FormDataSource _dataSource)
{
    if (_dataSource.table() == tablenum(CustTable))
    {
        CustTable custTable = _dataSource.cursor() as CustTable;
    
        if(custTable.AccountNum && strLen(custTable.AccountNum) > 8)
        {
            throw warning("@MET:METCustomerNumCheckDigits");
        }
    }
}

    /// <summary>
    /// Executes Application Suite specific logic after validating write of a generic record from the <c>DirPartyEntity</c> data source.
    /// </summary>
    /// <param name="_sender">The <c>DirPartyEntity</c> data source.</param>
    /// <param name="_e">The arguments for the event.</param>
    [FormDataSourceEventHandler(formDataSourceStr(DirPartyQuickCreateForm, DirPartyEntity), FormDataSourceEventType::ValidatedWrite)]
    public static void validatedWriteDirPartyEntityDataSourceEventHandler(FormDataSource _sender, FormDataSourceEventArgs _e)
    {
        var formRun                     = _sender.formRun() as FormRun;
        var dirPartyEntityDataSource    = formRun.dataSource(formDataSourceStr(DirPartyQuickCreateForm, DirPartyEntity)) as FormDataSource;

        if (dirPartyEntityDataSource.table() == tablenum(CustTable))
        {
            
            CustTable custTable = dirPartyEntityDataSource.cursor() as CustTable;
            if (CustTable::isDelayNumberSequenceGeneration() && custTable.METBusinessUnitTableRefRecId)
            {
                METBusinessUnitTableRefRecId    businessUnitTableRefRecId = custTable.METBusinessUnitTableRefRecId;

                METBusinessUnit   businessUnit = METBusinessUnit::findRecId(businessUnitTableRefRecId);
                if (businessUnit.RecId)
                {
                    NumberSeqFormHandler numSeqFormHandler = CustTable::getNumberSeqFormHandler(formRun, dirPartyEntityDataSource);
                    FormDataObject numberSequenceFormDataObject = numSeqFormHandler.parmFormDataSource().object(numSeqFormHandler.parmFieldIdNum());
                    custTable.AccountNum   = CustTable::metGetCustomerNumSeqRec(businessUnitTableRefRecId);
                    METDirPartyQuickCreateFormEventHandlers::validateNewCustomerAccountNum(formRun, _sender);
                }
            }
        }
    }
